const sql=require("mssql"),mssqlConfig={user:"sa",password:"#Global2025*",server:"localhost",database:"ErhanOzel",port:1433,options:{encrypt:!1,trustServerCertificate:!0}},CLINIC_ID=1;class DataMigrator{constructor(){this.mssqlPool=null,this.stats={users:0,services:0,patients:0,appointments:0,items:0,examinations:0}}async connect(){this.mssqlPool=await sql.connect(mssqlConfig)}async disconnect(){this.mssqlPool&&await this.mssqlPool.close()}async extractUsers(){const t=(await this.mssqlPool.request().query("\n            SELECT \n                TAKIPNO,\n                GIRISKODU,\n                ISIMSOYISIM,\n                GOREVNO,\n                IPTAL\n            FROM KULLANICILAR\n            WHERE TAKIPNO > 0\n            ORDER BY TAKIPNO\n        ")).recordset.map((t=>({legacy_id:t.TAKIPNO,username:(t.GIRISKODU||`user_${t.TAKIPNO}`).toLowerCase().substring(0,50),name:t.ISIMSOYISIM||`Kullanıcı ${t.TAKIPNO}`,role:this.mapUserRole(t.GOREVNO),is_active:t.IPTAL?0:1})));return this.stats.users=t.length,t}mapUserRole(t){switch(t){case 2:return"doctor";case 16:case 11:return"secretary";default:return"admin"}}async extractServices(){const t=(await this.mssqlPool.request().query("\n            SELECT \n                KOD,\n                ACIKLAMA,\n                FIYAT,\n                BUTFIYATI,\n                IPTAL\n            FROM TETKIK\n            WHERE ACIKLAMA IS NOT NULL AND ACIKLAMA != ''\n            ORDER BY KOD\n        ")).recordset.map((t=>({legacy_code:String(t.KOD),name:t.ACIKLAMA,price:t.FIYAT||t.BUTFIYATI||0,is_active:t.IPTAL?0:1})));return this.stats.services=t.length,t}async extractPatients(){const t=(await this.mssqlPool.request().query("\n            SELECT \n                HASTANO,\n                AD,\n                SOYAD,\n                KIMLIKNO,\n                EV_TELEFON,\n                EV_MOBIL,\n                EV_EMAIL,\n                DGMTRH,\n                DOGUMYERI,\n                CINSIYET,\n                KANGRUBU,\n                EV_ADRES1,\n                EV_ADRES2,\n                BABAADI,\n                ANNEADI,\n                MESLEK,\n                NK_UYRUGU,\n                NOTLAR,\n                IPTAL\n            FROM HST_ANADOSYA\n            ORDER BY HASTANO\n        ")).recordset.map((t=>({legacy_id:t.HASTANO,name:`${t.AD||""} ${t.SOYAD||""}`.trim()||`Hasta ${t.HASTANO}`,tc_no:t.KIMLIKNO||"",phone:t.EV_MOBIL||t.EV_TELEFON||"",email:t.EV_EMAIL||null,birth_date:t.DGMTRH?new Date(t.DGMTRH).toISOString().split("T")[0]:null,birth_place:t.DOGUMYERI||null,gender:"E"===t.CINSIYET?"M":"K"===t.CINSIYET?"F":"U",blood_type:t.KANGRUBU||null,address:[t.EV_ADRES1,t.EV_ADRES2].filter(Boolean).join(" ")||null,father_name:t.BABAADI||null,mother_name:t.ANNEADI||null,profession:t.MESLEK||null,nationality:t.NK_UYRUGU||"TR",notes:t.NOTLAR||null,status:t.IPTAL?0:1})));return this.stats.patients=t.length,t}async extractAppointments(){const t=(await this.mssqlPool.request().query("\n            SELECT \n                GELISNO,\n                PROTOKOLNO,\n                HASTANO,\n                DOKTOR_ID,\n                TARIH,\n                IPTAL\n            FROM HST_GELISLER\n            ORDER BY GELISNO\n        ")).recordset.map((t=>({legacy_visit_id:t.GELISNO,protocol_no:t.PROTOKOLNO||null,patient_legacy_id:t.HASTANO,doctor_legacy_id:t.DOKTOR_ID,appointment_date:t.TARIH?new Date(t.TARIH).toISOString().slice(0,19).replace("T"," "):null,status:t.IPTAL?"cancelled":"completed"})));return this.stats.appointments=t.length,t}async extractAppointmentItems(){const t=(await this.mssqlPool.request().query("\n            SELECT \n                i.RECORD_ID,\n                i.GELISNO,\n                i.ISLEMNO,\n                i.FIYAT,\n                i.ADET,\n                i.YAPAN,\n                t.ACIKLAMA as ISLEM_ADI\n            FROM HST_ISLEMLER i\n            LEFT JOIN TETKIK t ON i.ISLEMNO = t.KOD\n            ORDER BY i.GELISNO, i.RECORD_ID\n        ")).recordset.map((t=>({appointment_legacy_id:t.GELISNO,service_legacy_code:String(t.ISLEMNO),item_name:t.ISLEM_ADI||`İşlem ${t.ISLEMNO}`,quantity:t.ADET||1,unit_price:parseFloat(t.FIYAT)||0,total_price:(parseFloat(t.FIYAT)||0)*(t.ADET||1),performer_legacy_id:t.YAPAN})));return this.stats.items=t.length,t}async extractExaminations(){const t=(await this.mssqlPool.request().query("\n            WITH RankedTakip AS (\n                SELECT \n                    t.GELISNO,\n                    et.SIKAYETLER,\n                    et.HIKAYESI,\n                    et.BULGULAR,\n                    et.TESHIS,\n                    et.TEDAVI,\n                    et.SONUC,\n                    et.TARIH,\n                    ROW_NUMBER() OVER (\n                        PARTITION BY \n                            t.GELISNO, \n                            CONVERT(VARCHAR(19), et.TARIH, 120)\n                        ORDER BY et.TARIH DESC\n                    ) as rn\n                FROM HST_TIBBI_EPIKRIZ_TAKIP et\n                INNER JOIN HST_TIBBI_EPIKRIZ e ON et.EPIKRIZ_ID = e.ID\n                INNER JOIN HST_TIBBI t ON e.TIBBIDOSYA_ID = t.RECORD_ID\n            )\n            SELECT \n                GELISNO,\n                SIKAYETLER,\n                HIKAYESI,\n                BULGULAR,\n                TESHIS,\n                TEDAVI,\n                SONUC,\n                TARIH\n            FROM RankedTakip\n            WHERE rn = 1\n            ORDER BY GELISNO\n        ")).recordset.map((t=>({legacy_visit_id:t.GELISNO,complaint:t.SIKAYETLER||null,story:t.HIKAYESI||null,bulgular:t.BULGULAR||null,diagnosis:t.TESHIS||null,treatment:t.TEDAVI||null,result_note:t.SONUC||null,created_at:t.TARIH?new Date(t.TARIH).toISOString().slice(0,19).replace("T"," "):null})));return this.stats.examinations=t.length,t}async extractAll(){await this.connect();try{const t={clinic_id:1,extracted_at:(new Date).toISOString(),users:await this.extractUsers(),services:await this.extractServices(),patients:await this.extractPatients(),appointments:await this.extractAppointments(),appointment_items:await this.extractAppointmentItems(),examinations:await this.extractExaminations()},n=require("fs"),e="/home/zafer/htdocs/pozitif-klinik/docs/migration_data.json";return n.writeFileSync(e,JSON.stringify(t,null,2)),t}finally{await this.disconnect()}}}const migrator=new DataMigrator;migrator.extractAll().catch((t=>{process.exit(1)}));